CREATE OR REPLACE FUNCTION public.admin_list_users() RETURNS TABLE(user_id uuid,email text,display_name text,created_at timestamptz,is_admin boolean,role text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.user_id,p.email,p.display_name,p.created_at,public.has_role(p.user_id,'admin'),coalesce((SELECT a.role FROM public.user_role_assignments a JOIN public.roles r ON r.code=a.role AND r.is_active WHERE a.user_id=p.user_id AND a.is_active ORDER BY CASE a.role WHEN 'admin' THEN 0 ELSE 1 END,a.assigned_at DESC LIMIT 1),'user') FROM public.profiles p WHERE public.has_permission('users.directory','view') $$;
CREATE OR REPLACE FUNCTION public.admin_set_staff_state(_user uuid,_active boolean,_reassign_to uuid,_leave_unassigned boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrow jsonb;o record;BEGIN IF NOT public.has_permission('security.roles','edit') THEN RAISE EXCEPTION 'إدارة الحسابات للأدمن فقط';END IF;PERFORM public._assert_reason(_reason);PERFORM pg_advisory_xact_lock(60412026,9);IF _user=auth.uid() THEN RAISE EXCEPTION 'لا يمكنك إيقاف حسابك';END IF;IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_user) THEN RAISE EXCEPTION 'المستخدم غير موجود';END IF;IF public.has_role(_user,'admin') AND NOT _active AND (SELECT count(DISTINCT a.user_id) FROM public.user_role_assignments a WHERE a.role='admin' AND a.is_active AND NOT EXISTS(SELECT 1 FROM public.staff_accounts s WHERE s.user_id=a.user_id AND s.status='inactive'))<2 THEN RAISE EXCEPTION 'لا يمكن إيقاف آخر أدمن';END IF;IF NOT _active AND EXISTS(SELECT 1 FROM public.opportunities WHERE owner_user_id=_user AND outcome IS NULL) AND _reassign_to IS NULL AND NOT _leave_unassigned THEN RAISE EXCEPTION 'اختر إعادة التوزيع أو غير موزعة قبل إيقاف الحساب';END IF;IF _reassign_to=_user OR (_reassign_to IS NOT NULL AND NOT public.has_role(_reassign_to,'sales_agent')) THEN RAISE EXCEPTION 'اختر وسيطًا فعالًا مختلفًا';END IF;SELECT to_jsonb(s) INTO oldrow FROM public.staff_accounts s WHERE user_id=_user FOR UPDATE;IF NOT _active THEN FOR o IN SELECT * FROM public.opportunities WHERE owner_user_id=_user AND outcome IS NULL ORDER BY id FOR UPDATE LOOP UPDATE public.opportunities SET owner_user_id=_reassign_to,updated_at=now() WHERE id=o.id;INSERT INTO public.opportunity_owner_history(opportunity_id,from_owner,to_owner,reason,actor_id) VALUES(o.id,_user,_reassign_to,_reason,auth.uid());PERFORM public._safety_audit('STAFF_OPPORTUNITY_REASSIGNED','opportunities',o.id::text,to_jsonb(o),(SELECT to_jsonb(x) FROM public.opportunities x WHERE id=o.id),_reason);END LOOP;UPDATE public.tenant_login_links SET expires_at=least(expires_at,now()) WHERE tenant_account_id IN(SELECT id FROM public.tenant_accounts WHERE user_id=_user);END IF;INSERT INTO public.staff_accounts(user_id,status,deactivated_at,deactivated_by,reason,auth_sync_status) VALUES(_user,CASE WHEN _active THEN 'active' ELSE 'inactive' END,CASE WHEN NOT _active THEN now() END,auth.uid(),_reason,'pending') ON CONFLICT(user_id) DO UPDATE SET status=excluded.status,deactivated_at=excluded.deactivated_at,deactivated_by=excluded.deactivated_by,reason=excluded.reason,auth_sync_status='pending',updated_at=now();PERFORM public._safety_audit('STAFF_STATE_CHANGED','staff_accounts',_user::text,oldrow,(SELECT to_jsonb(s) FROM public.staff_accounts s WHERE user_id=_user),_reason);END $$;
CREATE TABLE IF NOT EXISTS public.staff_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL,role text NOT NULL REFERENCES public.roles(code),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','sent','accepted','failed','cancelled')),invited_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',accepted_by uuid,accepted_at timestamptz);GRANT SELECT ON public.staff_invitations TO authenticated;GRANT ALL ON public.staff_invitations TO service_role;ALTER TABLE public.staff_invitations ENABLE ROW LEVEL SECURITY;CREATE POLICY invitation_admin_read ON public.staff_invitations FOR SELECT TO authenticated USING(public.has_permission('users.directory','view'));
CREATE OR REPLACE FUNCTION public.admin_prepare_staff_invitation(_email text,_role text,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k uuid:=gen_random_uuid();BEGIN IF NOT public.has_permission('security.roles','edit') THEN RAISE EXCEPTION 'الدعوات للأدمن فقط';END IF;PERFORM public._assert_reason(_reason);IF _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR NOT EXISTS(SELECT 1 FROM public.roles WHERE code=_role AND is_active) OR _role IN('tenant','user') THEN RAISE EXCEPTION 'بريد أو دور موظف غير صالح';END IF;INSERT INTO public.staff_invitations(id,email,role,invited_by) VALUES(k,lower(btrim(_email)),_role,auth.uid());PERFORM public._safety_audit('STAFF_INVITATION_PREPARED','staff_invitations',k::text,NULL,jsonb_build_object('role',_role),_reason);RETURN k;END $$;
CREATE OR REPLACE FUNCTION public.staff_service_result(_id uuid,_user uuid,_success boolean,_invitation boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'خدمة الحسابات فقط';END IF;IF _invitation THEN UPDATE public.staff_invitations SET status=CASE WHEN _success THEN 'sent' ELSE 'failed' END WHERE id=_id AND status='pending';ELSE UPDATE public.staff_accounts SET auth_sync_status=CASE WHEN _success THEN 'synced' ELSE 'failed' END WHERE user_id=_user;END IF;END $$;
REVOKE ALL ON FUNCTION public.admin_set_staff_state(uuid,boolean,uuid,boolean,text),public.admin_prepare_staff_invitation(text,text,text),public.staff_service_result(uuid,uuid,boolean,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.admin_set_staff_state(uuid,boolean,uuid,boolean,text),public.admin_prepare_staff_invitation(text,text,text) TO authenticated;REVOKE ALL ON FUNCTION public.staff_service_result(uuid,uuid,boolean,boolean) FROM authenticated;GRANT EXECUTE ON FUNCTION public.staff_service_result(uuid,uuid,boolean,boolean) TO service_role;
SELECT to_regclass('public.staff_invitations') IS NOT NULL AS invitations_ready;